import React from 'react';
import ReactDOM from 'react-dom';

import Header from './Header';
import WatchList from './WatchList';
import Footer from './Footer';

function WatchlistPage() {
  return (
    <>
      <Header />
      <WatchList />
      <Footer />
    </>
  );
}

export default WatchlistPage;
